// ====================================================================
// PLAN CLEANUP v3 - STATS housekeeping
// Revisi 2026-08-27: aturan v2 (whitelist baris OFF) + FILTER UMUR.
//
// ATURAN
//   Baris DIPERTAHANKAN kalau memenuhi salah satu:
//     1. header (baris 1) - tidak pernah masuk hitungan
//     2. DILINDUNGI: bot_mode == "OFF" dan off_reason BUKAN "VIRA"
//        -> selamanya, tanpa kedaluwarsa. Ini kontak yang dipegang Sam.
//     3. masih hangat: aktivitas terakhir < RETENTION_DAYS hari lalu
//     4. tidak punya jejak waktu sama sekali -> umurnya tak bisa
//        dipastikan, jadi tidak disentuh (dilaporkan supaya dicek manual)
//
//   Baris DIHAPUS hanya kalau ketiganya benar:
//     tidak dilindungi  DAN  punya jejak waktu  DAN  jejaknya sudah lewat ambang
//
// KENAPA ADA FILTER UMUR (v2 belum punya)
//   Di v2, baris bot_mode = ON dihapus tanpa peduli umur. Orang yang baru
//   chat 30 September ikut hilang saat cleanup 1 Oktober - VIRA lalu
//   menyapanya seperti orang asing dan Counter/greeting_sent balik ke nol.
//
// KENAPA PATOKANNYA BUKAN last_reply_ts SAJA (beda dari Persada)
//   Di workflow utama, last_reply_ts HANYA ditulis node "Update to STATS",
//   dan node itu ada di cabang IF Bot Mode Active = ON. Kontak yang
//   di-OFF-kan tidak pernah memperbaruinya walau chat tiap hari - di data
//   nyata cuma 41% baris OFF yang punya last_reply_ts. Yang menyelamatkan
//   mereka adalah buffer_done_ts, ditulis "Delete_Pending_Msg_Bot_Off" di
//   cabang OFF. Karena itu umur diambil dari NILAI TERBESAR beberapa kolom,
//   dengan cadangan terakhir kolom tanggal berformat manusia.
//
// CATATAN UNIT: kolom ts di sheet ini campur - last_reply_ts/gform_sent_ts/
// kelas_anak_ts dalam DETIK, buffer_done_ts dalam MILIDETIK, dan `timestamp`
// campur keduanya antar-baris. Jadi normalisasi dilakukan PER NILAI.
// ====================================================================

const RETENTION_DAYS = 90;     // ambang "sudah lama" - ubah di sini
const OFF_VALUE      = 'OFF';
const DELETE_LABEL   = 'VIRA'; // satu-satunya off_reason yang boleh dihapus

// Urutan tidak penting - yang dipakai selalu nilai TERBESAR.
const TS_COLS = ['last_reply_ts', 'buffer_done_ts', 'timestamp',
                 'gform_sent_ts', 'kelas_anak_ts'];

const norm = v => String(v ?? '').trim().toUpperCase();

function toSec(v) {
  const n = Number(String(v ?? '').trim());
  if (!Number.isFinite(n) || n <= 0) return 0;
  return n > 1e12 ? Math.floor(n / 1000) : Math.floor(n);   // milidetik -> detik
}

// "16/06/2026" (yang ditulis Update to STATS) atau "2026-06-16".
function parseTanggal(v) {
  const s = String(v ?? '').trim();
  if (!s) return 0;
  let m = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  if (m) return Math.floor(Date.UTC(+m[3], +m[2] - 1, +m[1]) / 1000);
  m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return Math.floor(Date.UTC(+m[1], +m[2] - 1, +m[3]) / 1000);
  return 0;
}

function lastActivity(r) {
  let best = 0;
  for (const c of TS_COLS) {
    const n = toSec(r[c]);
    if (n > best) best = n;
  }
  if (!best) best = parseTanggal(r['Tanggal Chat Terakhir']) || parseTanggal(r['Tanggal Chat Pertama']);
  return best;
}

const now = Math.floor(Date.now() / 1000);
const cutoff = now - RETENTION_DAYS * 86400;

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && typeof r === 'object'
            && r.row_number !== undefined
            && Number(r.row_number) >= 2);

if (!rows.length) {
  console.log('STATS kosong / hanya header - tidak ada yang dibersihkan.');
  return [];
}

// --------------------------------------------------------------
// Guard 1: pastikan yang terbaca benar-benar tab STATS.
// --------------------------------------------------------------
if (!rows.some(r => 'No WA' in r)) {
  throw new Error('Kolom "No WA" tidak ditemukan - tab yang terbaca kemungkinan bukan STATS. Cleanup DIBATALKAN.');
}

// --------------------------------------------------------------
// Guard 2 (KRITIS): tanpa bot_mode, tidak ada baris yang terlindungi.
// --------------------------------------------------------------
if (!rows.some(r => 'bot_mode' in r)) {
  throw new Error('Kolom "bot_mode" tidak ditemukan di STATS. Tanpa kolom ini tidak ada baris yang terlindungi. Cleanup DIBATALKAN.');
}

// --------------------------------------------------------------
// Guard 3 (KRITIS): minimal satu kolom patokan umur harus ada, kalau
// tidak semua baris terbaca "tanpa jejak" dan cleanup jadi mubazir -
// atau lebih buruk, salah menilai umur. Kolom tanggal manusia dihitung
// sebagai patokan yang sah.
// --------------------------------------------------------------
const AGE_COLS = TS_COLS.concat(['Tanggal Chat Terakhir', 'Tanggal Chat Pertama']);
if (!AGE_COLS.some(c => rows.some(r => c in r))) {
  throw new Error('Tidak ada satu pun kolom patokan umur (' + AGE_COLS.join(', ') + ') di STATS. Cleanup DIBATALKAN.');
}

// --------------------------------------------------------------
// Guard 4 (peringatan): off_reason. Kalau kolomnya belum ada, semua
// baris OFF terbaca tanpa label -> semuanya dilindungi. Aman, cuma
// kurang bersih; cukup ditandai di laporan.
// --------------------------------------------------------------
const hasOffReason = rows.some(r => 'off_reason' in r);

const delRowNums = [];
const noTsRows   = [];
let protSam = 0, protBlank = 0, protOther = 0;   // dilindungi (OFF non-VIRA)
let keepHangat = 0, keepTanpaJejak = 0;          // dipertahankan karena umur
let delOffVira = 0, delNotOff = 0;               // dihapus

for (const r of rows) {
  const mode   = norm(r.bot_mode);
  const reason = norm(r.off_reason);

  // --- lapis 1: perlindungan permanen -------------------------
  if (mode === OFF_VALUE && reason !== DELETE_LABEL) {
    if (reason === 'SAM')     protSam++;
    else if (reason === '')   protBlank++;
    else                      protOther++;
    continue;
  }

  // --- lapis 2: filter umur -----------------------------------
  const act = lastActivity(r);
  if (!act) {
    keepTanpaJejak++;
    noTsRows.push(Number(r.row_number) + '(' + String(r['No WA'] ?? '').trim() + ')');
    continue;
  }
  if (act >= cutoff) {
    keepHangat++;
    continue;
  }

  if (mode === OFF_VALUE) delOffVira++;   // OFF + VIRA, dan sudah lama
  else                    delNotOff++;    // bot aktif, dan sudah lama
  delRowNums.push(Number(r.row_number));
}

const totalDataRows = rows.length;
const deleteCount   = delRowNums.length;
const keepCount     = totalDataRows - deleteCount;

// --------------------------------------------------------------
// Blok penghapusan.
// v1/v2 memakai "salin yang disimpan ke bawah, lalu hapus blok 2..N".
// Itu masuk akal saat yang disimpan cuma segelintir baris SAM. Dengan
// filter umur, MAYORITAS baris justru dipertahankan - menyalin ratusan
// baris lalu menghapus blok raksasa jadi mahal dan berisiko.
// v3 memakai pendekatan Persada: hapus hanya baris yang memang kena,
// dikelompokkan jadi blok kontigu, diurutkan MENURUN supaya nomor baris
// di atasnya tetap valid setelah blok di bawahnya hilang. Baris yang
// dipertahankan tidak pernah disentuh sama sekali.
// --------------------------------------------------------------
delRowNums.sort((a, b) => a - b);
const blocks = [];
for (const n of delRowNums) {
  const last = blocks[blocks.length - 1];
  if (last && n === last.startRow + last.count) last.count++;
  else blocks.push({ startRow: n, count: 1 });
}
blocks.reverse();

const L = [];
L.push('[VIRA] STATS Cleanup v3');
L.push('');
L.push('Total baris data : ' + totalDataRows);
L.push('Dipertahankan    : ' + keepCount);
L.push('Dihapus          : ' + deleteCount + (blocks.length ? ' (' + blocks.length + ' blok)' : ''));
L.push('');
L.push('Dipertahankan karena:');
L.push('- Dipegang Sam (OFF + SAM)   : ' + protSam);
L.push('- OFF tanpa label           : ' + protBlank);
if (protOther) L.push('- OFF label lain            : ' + protOther);
L.push('- Masih hangat (< ' + RETENTION_DAYS + ' hari) : ' + keepHangat);
L.push('- Tanpa jejak waktu         : ' + keepTanpaJejak);
if (deleteCount) {
  L.push('');
  L.push('Dihapus karena lewat ' + RETENTION_DAYS + ' hari:');
  L.push('- Bot masih aktif           : ' + delNotOff);
  L.push('- OFF by VIRA               : ' + delOffVira);
}
if (!hasOffReason) {
  L.push('');
  L.push('PERINGATAN: kolom off_reason belum ada di STATS - semua baris OFF diperlakukan sebagai dilindungi.');
}
if (keepTanpaJejak) {
  L.push('');
  L.push('PERLU DICEK: ' + keepTanpaJejak + ' baris tanpa jejak waktu apa pun, sengaja tidak disentuh.');
  L.push('Baris: ' + noTsRows.slice(0, 15).join(', ') + (noTsRows.length > 15 ? ', +' + (noTsRows.length - 15) + ' lagi' : ''));
}
const report = L.join('\n');

console.log('STATS cleanup v3: ' + totalDataRows + ' baris | ' + keepCount + ' dipertahankan | '
  + deleteCount + ' dihapus dalam ' + blocks.length + ' blok.');
if (blocks.length > 40) {
  console.warn('PERHATIAN: ' + blocks.length + ' blok hapus - mendekati kuota tulis Google Sheets (60/menit). Node Delete sudah retry otomatis, tapi pantau hasilnya.');
}

return [{ json: {
  retentionDays: RETENTION_DAYS,
  totalDataRows, keepCount, deleteCount,
  protSam, protBlank, protOther,
  keepHangat, keepTanpaJejak,
  delOffVira, delNotOff,
  hasOffReason,
  blocks, blockCount: blocks.length,
  noTsRows,
  report,
} }];

// Pecah daftar blok jadi item terpisah supaya node Delete jalan sekali
// per blok. Urutannya sudah MENURUN dari Plan cleanup - jangan diurutkan
// ulang, kalau naik maka penghapusan blok atas akan menggeser nomor baris
// blok di bawahnya dan yang terhapus jadi baris yang salah.
const plan = $('Plan cleanup').first().json;
const blocks = plan.blocks || [];

if (!blocks.length) {
  console.log('Tidak ada blok untuk dihapus.');
  return [];
}

console.log('Menghapus ' + plan.deleteCount + ' baris dalam ' + blocks.length + ' blok (dari bawah ke atas).');
return blocks.map(b => ({ json: b }));

// Node ini WAJIB mengeluarkan TEPAT 1 item.
// Node Delete jalan sekali per blok, jadi tanpa penciutan ini notifikasi
// WA akan terkirim berkali-kali - satu per blok yang dihapus.
const plan = $('Plan cleanup').first().json;
console.log('Cleanup selesai: ' + plan.deleteCount + ' baris dihapus, ' + plan.keepCount + ' dipertahankan.');
return [{ json: plan }];
